#pragma once
// StereoPoC.h - single-pass instanced stereo: camera-dependent geometry draws (world + 1st-person camera; this
// round: every GBuffer writer and the z-prepass) are drawn once with 2x the instances into the two halves of a
// double-wide (2W x H) engine render. Replacement VS = bytecode twins of the engine's VS (StereoVS.pack,
// generated by proto/stereo/tools/gen_stereo_vs.py: original program + per-eye clip-space correction
// D_e = VP_mono^-1 VP_e from b5 + squeeze + seam clip distance), plus the PoC's HLSL debug shaders.
// Design and experiments: analysis/stereo-poc-plan.md (sections 12, 13).
//
// Integration points (all in the main plugin, see plan section 8):
//   F4SEPlugin_Load (after the 1.11.240 check) : stereo::Configure(), stereo::InstallCameraHook()
//   rendersize::HkCreate, after the real call   : stereo::OnDeviceCreated(*a_device, *a_ctx)
//   Presenter, after BeginFrame                 : stereo::PublishEyes() for the frame about to render
//   Presenter, at submit                        : stereo::SplitDoubleWide() + runtime.SubmitEye(0/1)
//   Presenter, every Present                    : stereo::OnPresent()
//   CommandChannel                              : "stereo <mode>", "stereocap <path>", "stereostat"

#include <cstdint>
#include <string>
#include <vector>

struct ID3D11Device;
struct ID3D11DeviceContext;
struct ID3D11Texture2D;

namespace fo4flatvr::stereo
{
    enum class Mode : int
    {
        // Numbering = ini [Stereo] iMode and pipe "stereo <n>".
        kOff = 0,             // no hooks act (installed hooks are pure pass-through)
        kCensus = 1,          // observe only: count/classify draws, log targets/formats/depth state
        kStereoDebug = 2,     // 2 instances, simplified VS + debug PS (depth band / cell hash)
        kStereoFaithful = 3,  // 2 instances, faithful VS, engine GBuffer PS kept
        kIdentity = 4,        // diagnostic: faithful VS replaces the target VS but draws mono with the engine's ViewProj
    };

    struct Config
    {
        Mode        mode{ Mode::kOff };
        bool        skipUnconverted{ false };  // drop camera-dependent geometry draws we cannot convert
                                               // (world camera only) - clean images for the metrics
        bool        testEyes{ false };         // synthetic parallel symmetric eyes instead of the headset's
        float       testIpdMeters{ 0.064f };
        float       testHalfFovDeg{ 45.0f };   // horizontal half FOV of each test eye
        float       unitsPerMeter{ 70.0f };    // same scale as head position (Settings::unitsPerMeter)
        int         eyeWidth{ 0 };             // pixels per eye (render width / 2); for logs and checks
        int         eyeHeight{ 0 };
        int         seamPad{ 0 };              // guard px per eye (seamPad / 2 left of the eye image, the rest right; rendered
                                               // with extra FOV, cropped at submission): region = eyeWidth + seamPad (RenderSize.h)
        int         renderWidth{ 0 };          // back-buffer width (0 = unknown: 2 * eyeWidth)
        std::string shaderDir;                 // folder with StereoVS.hlsl / StereoDebugPS.hlsl / StereoCommon.hlsli
        int         logEveryFrames{ 600 };
        bool        noJitter{ false };         // force BSGraphics::State+0xAC = 0 (no TAA jitter) for A/B captures
        bool        ownDepth{ true };          // stereo modes: skip the world z-prepass, GBuffer geometry writes depth (R1)
                                               // (fallback when the prepass cannot be converted, see stereoPrepass)
        bool        stereoPrepass{ true };     // convert the z-prepass draws too (early-Z kept, engine depth states)
        bool        firstPerson{ true };       // the 1st-person camera (arms/weapon) is a stereo camera as well
        int         scope{ 1 };                // 0: GBuffer writers + prepass; 1: every camera draw whose VS has a twin (forward too)
        bool        clearGBuffer{ false };     // measurement: clear all GBuffer targets at the frame's first GBuffer draw
        // ---- lighting/post round (stereo-poc-plan.md section 14) ----
        bool        split{ true };             // per-eye b12 copies + split draws (lights, composite, water, decals, ...)
        bool        saoPerEye{ true };         // SAO RawAO PS split with a per-eye projInfo (cb2[0])
        bool        taaPerEye{ true };         // per-eye TAA: motion vectors converted per eye before the TAA resolve, jitter per eye
        // Cut list, applied while a stereo mode (2/3) is configured (or forced by "stereocuts force"):
        bool        cutTaa{ false };           // TAA off, FXAA on (default off since per-eye TAA: taaPerEye)
        bool        cutMotionBlur{ false };    // bMBEnable:Imagespace (per-eye: StereoPost.inl)
        bool        cutDof{ false };           // bDoDepthOfField:Imagespace (per eye as is: blur kernels, guard bands)
        bool        cutLensFlare{ false };     // bLensFlare:ImageSpace (per-eye: StereoPost.inl)
        bool        cutGodrays{ true };        // bVolumetricLightingEnable:Display (NVIDIA godrays)
        bool        cutSsr{ false };           // screen-space reflections (runtime flag + the SSR/SAO-CS effect); per eye: split prepass + g144 twin
        bool        cutHbao{ true };           // bEnable:NVHBAO (HBAO+; SAO stays)
        double      eyeFarScale{ 2.0 };
        bool        keepMonoDepthClip{ true };  // VS twins clamp eye z to [0, w] where mono z was inside (sky / pinned passes)        // eye far plane = x * mono far (StereoMath g_eyeFarScale)
        bool        cutTiled{ false };         // bComputeShaderDeferredTiledLighting:Display (lights -> volume draws)
        bool        saoPixelShader{ true };    // SAO through its PS variant (splittable) instead of the CS variant
        bool        hiddenAreaMask{ true };    // 22 Nov: lens-hidden area (XR_KHR_visibility_mask) stamped into depth (HiddenArea.inl)
        bool        cutSao{ true };            // SAO off in stereo (FO4VR forces AO off); 0 = per-eye SAO option
        int         forceCuts{ 0 };            // diagnostic: 0 auto (stereo frames only), 1 always, -1 never
    };

    // Eye data for the frame about to be rendered, straight from xr::FrameInfo (reference space,
    // OpenXR conventions, metres, radians). The module converts to the engine's view space itself.
    struct EyeFrame
    {
        bool  valid{ false };
        float headQ[4]{ 0, 0, 0, 1 }, headP[3]{};
        float eyeQ[2][4]{ { 0, 0, 0, 1 }, { 0, 0, 0, 1 } }, eyeP[2][3]{};
        float fov[2][4]{};  // angleLeft, angleRight, angleUp, angleDown (XrFovf order)
    };

    void Configure(const Config& a_config);
    // Device/context vtable hooks are only installed by OnDeviceCreated after this was set (F4SEPlugin_Load:
    // iMode != 0 or bInstallHooks=1). Off = no D3D patches at all.
    void SetHooksEnabled(bool a_on);
    bool HooksEnabled();
    Config CurrentConfig();
    void SetMode(Mode a_mode);

    // Hooks BSGraphics::State::SetCameraData (1.11.240 rva 182BC80) with a byte-checked entry detour.
    // Call once from F4SEPlugin_Load, before the renderer runs.
    bool InstallCameraHook();

    // Patches the device (CreateVertexShader, CreateDeferredContext) and immediate-context vtables
    // (VSSetShader, PSSetShader, Draw*, OMSetRenderTargets, OMSetDepthStencilState, ClearState) and
    // compiles the replacement shaders. Must run before the engine loads its shaders: call it from the
    // D3D11CreateDeviceAndSwapChain IAT hook right after the real call succeeds.
    void OnDeviceCreated(ID3D11Device* a_device, ID3D11DeviceContext* a_immediate);

    void PublishEyes(const EyeFrame& a_eyes);

    // 22 Nov (hidden-area agent): the runtime's XR_KHR_visibility_mask state and, when a_serial is new, the hidden-triangle
    // mesh per eye (view-space tangents x, y on z = -1; three indices per triangle). Presenter, after PollEvents.
    void SetHiddenAreaMask(bool a_extension, std::uint64_t a_serial, const std::vector<float> a_xy[2], const std::vector<std::uint32_t> a_indices[2]);

    // Stereo modes with test eyes: horizontal FOV (deg) the world NiCamera needs so that its frustum (aspect =
    // back-buffer aspect a_aspect) contains both synthetic eyes; 0 otherwise.
    float TestEyesRenderHFovDeg(float a_aspect);

    // The eye pose/FOV actually used for the frame now being presented (for SubmitEye). In testEyes mode
    // these are the synthetic eyes. Returns false if no stereo frame was rendered.
    bool UsedEyes(EyeFrame& a_out);

    // Copies the left/right halves of a double-wide image into two internal W x H textures (recreated on
    // size/format change). Returned pointers are owned by the module and valid until the next call.
    bool SplitDoubleWide(ID3D11DeviceContext* a_ctx, ID3D11Texture2D* a_src, ID3D11Texture2D*& a_left,
        ID3D11Texture2D*& a_right);

    // Per-frame bookkeeping: statistics log, pending capture write-out. Call once per Present (game thread),
    // before the real Present; AfterPresent right after it returns (CPU frame time = AfterPresent -> OnPresent).
    void OnPresent();
    // "gpuprof" (GpuProf.inl): names the GPU work from here to the next mark; "" = back to per-render-target keys. Render thread.
    void GpuProfMark(const char* a_name);
    // Perf pass 26 Nov: the two eyes' real pixels inside the double-wide back buffer (guard bands left out; the same
    // regions SplitDoubleWide copies): eye e = [a_x[e], a_x[e] + a_width) x [0, a_height).
    bool EyeRegions(ID3D11Texture2D* a_src, unsigned a_x[2], unsigned& a_width, unsigned& a_height);
    void AfterPresent();
    // VATS camera window (VatsWindow.cpp): set around its own second-camera render so the frame-level hooks (per-eye
    // MV fix, post split, shadow signatures) leave it alone; its draws are gate 0 (own NiCamera) anyway.
    void SetSecondCameraPass(bool a_on);
    // Engine off-screen renders that are not a view of the world (FaceGen customization textures, 19 Nov black-face fix):
    // while one runs, no draw is converted whatever camera the gate still holds from the last SetCameraData.
    // a_mode: 0 bypass (default), 1 pass as before (measure only), 2 force the world-camera gate (diagnostic).
    void BeginEngineOffscreen();
    void EndEngineOffscreen();
    void SetEngineOffscreenMode(int a_mode);
    std::string EngineOffscreenStatus();
    bool StereoSubmitActive();  // mode 2/3 and a stereo world camera was built for the frame being presented

    // Capture render target 0 as it stands after the last converted draw of the next frame (BMP).
    void RequestCapture(std::string a_path);

    std::string Status();

    // Diagnostics: log every draw of the next frame, aggregated by (VS + DXBC key, gate, call, RTV count, action).
    void RequestDrawDump();

    // Measurement: for the next frame, snapshot every GBuffer render target after the frame's last GBuffer draw
    // and log per target the share of texels whose left and right halves are identical ("stereogb:" lines);
    // writes <stem>_rt0.bmp and <stem>_rt<i>_diff.pgm (255 = halves differ). a_coverage additionally binds
    // marker pixel shaders on GBuffer draws (converted = green, camera draw not converted = red, no stereo
    // camera = blue) and clears the targets first, so <stem>_rt0.bmp is a per-pixel coverage map.
    void RequestGBufferCapture(std::string a_stem, bool a_coverage);

    // Measurement (lighting round): for the next frame, snapshot render target 0 after the frame's last draw of
    // each stage - "light" (g009 deferred lights), "composite" (g010), "sao" (g125 SAO RawAO) - and log the halves
    // identity per stage ("stereostage:" lines, full frame and without a 64-px band at the seam/outer edges);
    // writes <stem>_<stage>.bmp (float targets clamped to [0,1]).
    void RequestStageCapture(std::string a_stem);

    // Pipe commands of the lighting round (stereosplit, stereosao, stereocut, stereocuts, stereostagecap); returns
    // "" for a verb it does not know.
    std::string Command(const std::string& a_verb, const std::string& a_arg);
}
